{"path": "kv.py", "content": "def parse_kv(text):
    """Parse 'a=1;b=2' into {'a': 1, 'b': 2}. Values are integers. Empty segments and spaces around keys and values are ignored."""
    result = {}
    for segment in text.split(';'):
        if not segment.strip():
            continue
        key, _, value = segment.partition('=')
        result[key.strip()] = int(value.strip())
    return result
